<script setup>
import {ref,onMounted} from 'vue'
import PortPicker from './PortPicker.vue'
import {api,post,references,portLabel,boxes,csrfHeaders} from './quotationApi'
const props=defineProps({initialPreview:Boolean,user:Object}),emit=defineEmits(['manual'])
const refs=ref({ports:[],carriers:[]}),preview=ref(props.initialPreview)
const initialFilters=()=>({origin_port_id:'',destination_port_id:'',carrier_id:'',etd:'',date_scope:'applicable',sort_by:'destination',descending:false,page:1,page_size:20})
const filters=ref(initialFilters()),selected=ref(Object.fromEntries(boxes.map(b=>[b,false]))),quantities=ref(Object.fromEntries(boxes.map(b=>[b,'1'])))
const result=ref(null),error=ref(''),busy=ref(false),ready=ref(false),originPicker=ref(null),destinationPicker=ref(null)
const exporting=ref(false),exportMessage=ref('')
async function exportExcel(){
  if(!result.value||result.value.source!=='published'||exporting.value)return
  exporting.value=true;error.value='';exportMessage.value=''
  const applied=JSON.parse(JSON.stringify(result.value.applied_filters)),referenceDate=result.value.reference_date
  try{
    const response=await fetch('/api/excel/export',{method:'POST',headers:{...csrfHeaders(),'Content-Type':'application/json'},body:JSON.stringify(applied),signal:AbortSignal.timeout(60000)})
    if(!response.ok){const data=await response.json();throw new Error(data.error?.message||'导出失败')}
    const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a')
    link.href=url;link.download=`内部海运报价_${referenceDate}.xlsx`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)
    exportMessage.value=`已导出${response.headers.get('X-Export-Count')}条正式报价，按上次成功查询的条件全量导出，不受分页影响。`
  }catch(e){error.value=e.message}finally{exporting.value=false}
}
async function search(page=1){
  if(!ready.value||busy.value)return
  error.value='';const values={}
  for(const box of boxes)if(selected.value[box]){if(!/^[1-9]\d{0,5}$/.test(quantities.value[box])||Number(quantities.value[box])>100000){error.value='已选箱型的箱量须为1～100000的整数';result.value=null;return}values[box]=Number(quantities.value[box])}
  if(originPicker.value?.hasUnresolvedSearch()||destinationPicker.value?.hasUnresolvedSearch()){error.value='检索港口后，请在候选列表中明确选择港口';result.value=null;return}
  busy.value=true;filters.value.page=page
  try{result.value=await post(preview.value?'/api/manual-drafts/search':'/api/quotes/search',{...filters.value,quantities:values})}catch(e){error.value=e.message;result.value=null}finally{busy.value=false}
}
async function reset(){try{const defaults=await api('/api/manual-drafts/defaults');filters.value={...initialFilters(),origin_port_id:defaults.data.origin_port_id};selected.value=Object.fromEntries(boxes.map(b=>[b,false]));originPicker.value?.clearSearch();destinationPicker.value?.clearSearch();await search()}catch(e){error.value=e.message}}
onMounted(async()=>{try{refs.value=await references();const initial=await api('/api/manual-drafts/defaults');filters.value.origin_port_id=initial.data.origin_port_id;ready.value=true;await search()}catch(e){error.value=e.message}})
async function revise(row){try{await post(`/api/quotes/${row.quote_id}/revision`,{});emit('manual')}catch(e){error.value=e.message}}
const historyData=ref(null),stopReason=ref(''),stopTarget=ref(null)
async function history(row){try{historyData.value=await api(`/api/quotes/${row.quote_id}/history`)}catch(e){error.value=e.message}}
async function disable(){try{await post(`/api/quotes/${stopTarget.value.quote_id}/disable`,{reason:stopReason.value});stopTarget.value=null;stopReason.value='';await search()}catch(e){error.value=e.message}}
</script>
<template><section class="quotes-panel">
  <div class="catalog-heading"><div><h2>价格查询</h2><p>按港口、船公司和开船日查找适用报价。</p></div><div class="form-actions"><button class="small-button primary" :disabled="busy||exporting||!result?.total||result?.source!=='published'" @click="exportExcel">{{exporting?'导出中…':'导出全部查询结果'}}</button><button class="small-button" @click="emit('manual')">录入／导入报价</button></div></div>
  <div class="query-mode"><label>查询范围<select v-model="preview" :disabled="busy" @change="result=null;search()"><option :value="false">正式报价（已审批）</option><option :value="true">草稿试查（未审批）</option></select></label><p v-if="preview" class="quote-banner">草稿试查：只展示字段检查通过的人工草稿，未审批，不可作为正式报价。</p><p v-else class="catalog-note">正式查询不包含草稿。仅展示已审批入库的当前有效版本。</p></div>
  <form class="catalog-form quote-form" @submit.prevent="search()"><fieldset :disabled="busy||!ready"><div class="form-fields"><PortPicker ref="originPicker" label="起运港" v-model="filters.origin_port_id" :ports="refs.ports" allow-all/><PortPicker ref="destinationPicker" label="目的港" v-model="filters.destination_port_id" :ports="refs.ports" allow-all/>
    <label>船公司<select v-model="filters.carrier_id"><option value="">全部船公司</option><option v-for="c in refs.carriers" :key="c.id" :value="c.id">{{c.name}}{{c.active?'':'（停用资料）'}}</option></select></label><label>ETD开船日<input type="date" v-model="filters.etd"><small>留空按公司当天日期判断；不核验实际船期。</small></label><label>有效期范围<select v-model="filters.date_scope"><option value="applicable">参考日适用</option><option value="all">全部有效期（含未来／过期）</option></select></label><label>排序<select v-model="filters.sort_by"><option value="destination">目的港</option><option value="carrier">船公司</option><option value="valid_to">有效期止</option><option value="transit_days">航程天数</option></select></label><label class="check-label"><input type="checkbox" v-model="filters.descending">降序</label></div>
    <div class="box-prices"><div v-for="box in boxes" :key="box"><label class="check-label"><input type="checkbox" v-model="selected[box]">计算{{box}}</label><label>{{box}}箱量<input v-model="quantities[box]" :disabled="!selected[box]" inputmode="numeric" maxlength="6"></label></div></div><div class="form-actions"><button class="small-button primary" type="submit">{{busy?'查询中…':'查询价格'}}</button><button class="small-button" type="button" @click="reset">重置条件</button></div><p class="catalog-note">修改条件后点击“查询价格”应用。空价格不当作零元；小计只在同一报价内计算，不跨来源拼单或换汇。</p></fieldset></form>
  <p v-if="error" role="alert" class="feedback error">{{error}}</p><p v-if="exportMessage" role="status" class="feedback success">{{exportMessage}}</p><p class="catalog-note">导出使用上次成功查询的条件与参考日期，重新读取全部正式报价；修改条件后请先查询。未审批草稿不导出。</p>
  <section v-if="stopTarget" class="quote-banner"><p>停用 {{stopTarget.service_key}} 后将从正式查询中移除，历史保留。</p><label>停用原因<input v-model="stopReason" maxlength="2000"></label><button :disabled="!stopReason.trim()" @click="disable">确认停用</button><button @click="stopTarget=null">取消</button></section><details v-if="historyData" open><summary>报价版本历史 <button @click="historyData=null">关闭</button></summary><article v-for="v in historyData.items" :key="v.id" class="quote-card"><h3>版本 {{v.version}} · {{v.is_current?'当前版本':'历史版本'}}</h3><p>{{v.service_key}} · {{v.valid_from}} ～ {{v.valid_to}} · {{v.currency}}</p><p v-for="p in v.prices" :key="p.container_type">{{p.container_type}}：{{(p.amount_minor/100).toFixed(2)}} {{v.currency}}</p><p>已含：{{v.included_fees}} · 另计：{{v.extra_fees}} · 待确认：{{v.unknown_fees}}</p><p>条件：{{v.conditions||'无'}} · 备注：{{v.remark}}</p><p>提交人 {{v.created_by}} · 审批人 {{v.approved_by}} · {{v.approved_at}} UTC</p><p v-for="e in v.evidence" :key="e.id">{{e.original_name}} {{e.worksheet}} {{e.cell_range}} {{e.manual_note}} <a v-if="e.file_id" :href="`/api/uploads/files/${e.file_id}/original`" download>下载原件核对</a></p></article></details><template v-if="result"><div class="query-result-head"><b>共 {{result.total}} 条{{result.source==='draft_preview'?'未审批草稿':'正式报价'}}</b><span>参考日期 {{result.reference_date}}</span><span v-for="(count,state) in result.status_counts" :key="state">{{state}} {{count}}</span></div><p class="catalog-note">{{result.notice}}<span v-if="result.excluded_incomplete_drafts">；另有{{result.excluded_incomplete_drafts}}条未补齐草稿未纳入试查。</span></p>
    <div class="quote-results"><article v-for="row in result.items" :key="row.id" class="quote-card"><div class="quote-card-heading"><div><small>{{row.region.name}} ／ {{row.route.name}}</small><h3>{{row.destination.name_cn||row.destination.name_en}} <span>{{row.destination.name_en}}</span></h3><p>{{portLabel(row.origin)}} → {{portLabel(row.destination)}}</p></div><div><span class="badge">{{row.date_status}}</span><span class="badge" v-if="row.preview">草稿 · 未审批</span></div></div>
      <dl class="quote-details"><div><dt>船公司</dt><dd>{{row.carrier.name}}</dd></div><div><dt>价格来源</dt><dd>{{row.supplier.name}} · {{row.series.name}}</dd></div><div><dt>服务／路径</dt><dd>{{row.service_key}} · {{row.service_kind==='direct'?'直达':'中转'}}<br>{{row.path_text||'未说明'}}</dd></div><div><dt>船期／航程</dt><dd>{{row.sailing||'未说明'}} · {{row.transit_days?row.transit_days+'天':'航程未说明'}}</dd></div><div><dt>有效期</dt><dd>{{row.valid_from}} ～ {{row.valid_to}}<br>依据：{{row.validity_basis}}</dd></div><div><dt>费用口径</dt><dd>{{row.fee_basis}}</dd></div></dl>
      <div class="price-strip"><div v-for="box in boxes" :key="box"><small>{{box}}</small><b>{{row.prices[box]??'缺价'}}</b><span>{{row.currency}}／箱</span></div><div v-if="row.subtotal!==null" class="subtotal"><small>海运费小计</small><b>{{row.subtotal}}</b><span>{{row.currency}}</span></div><div v-else-if="row.missing_boxes.length" class="missing-price">缺少所选箱型价格：{{row.missing_boxes.join('、')}}<br>无法计算完整小计</div></div>
      <p v-if="Object.keys(row.quantities).length" class="catalog-note">本次箱量：{{Object.entries(row.quantities).map(([box,n])=>`${n}×${box}`).join('＋')}}。{{row.subtotal_note}}</p><div class="fee-notes"><p><b>已含费用：</b>{{row.included_fees||'未说明'}}　<b>另计费用：</b>{{row.extra_fees||'未说明'}}</p><p><b>待确认费用：</b>{{row.unknown_fees||'未说明'}}</p><p v-if="row.conditions" class="condition-warning"><b>适用条件需确认：</b>{{row.conditions}}</p><p v-if="row.remark"><b>备注：</b>{{row.remark}}</p></div><small class="record-id">{{row.preview?'草稿编号':'版本编号'}} {{row.id}} · 修订{{row.version}}</small>
    <div v-if="!row.preview" class="form-actions"><button @click="revise(row)">修订此报价</button><button @click="history(row)">查看版本历史</button><button v-if="user?.role==='admin'" @click="stopTarget=row">停用报价</button></div></article><div v-if="!result.items.length" class="empty-quotes">没有符合条件的{{preview?'可试查草稿':'正式报价'}}。可调整日期范围、港口或船公司条件。{{preview?'请先补齐草稿中的待修正项。':'未审批草稿不会显示在这里。'}}</div></div>
    <div class="pagination"><button class="small-button" :disabled="busy||result.page<=1" @click="search(result.page-1)">上一页</button><span>第{{result.page}}页 ／ {{Math.max(1,Math.ceil(result.total/result.page_size))}}页</span><button class="small-button" :disabled="busy||result.page*result.page_size>=result.total" @click="search(result.page+1)">下一页</button><label>每页<select v-model.number="filters.page_size" :disabled="busy" @change="search()"><option :value="10">10条</option><option :value="20">20条</option><option :value="50">50条</option></select></label></div>
  </template>
</section></template>
